def padded(n, np_, rows, item):
    s = ST.Storage(DEV, item * rows * n)
    key = FM.rows_key(n, np_)
    s.form(key, 2 * rows * np_)
    s.wrote(key)
    return s, key


def facts():
    out = {}
    for name, n, np_, item in (("whole", 64, 96, 2), ("part", 10, 16, 2), ("f32", 10, 16, 4)):
        s, key = padded(n, np_, 4, item)
        n0 = len(DEV.runs)
        FM.compact(DEV, s, key, item)
        out[name] = {"runs": [r.name.rsplit("_", 1)[0] for r in DEV.runs[n0:]], "valid": form_keys(s)}
        s.free()
    return out
